class _BaseController(ABC):  # noqa: B024
    session: Session = Depends(generate_session)
    translator: Translator = Depends(get_locale_provider)
    locale_config: LocaleConfig = Depends(get_locale_config)

    _repos: AllRepositories | None = None
    _logger: Logger | None = None
    _settings: AppSettings | None = None
    _folders: AppDirectories | None = None

    @property
    def t(self):
        return self.translator.t if self.translator else get_locale_provider().t

    @property
    def repos(self):
        if not self._repos:
            self._repos = AllRepositories(self.session, group_id=self.group_id, household_id=self.household_id)
        return self._repos

    @property
    def logger(self) -> Logger:
        if not self._logger:
            self._logger = get_logger()
        return self._logger

    @property
    def settings(self) -> AppSettings:
        if not self._settings:
            self._settings = get_app_settings()
        return self._settings

    @property
    def folders(self) -> AppDirectories:
        if not self._folders:
            self._folders = get_app_dirs()
        return self._folders

    @property
    def group_id(self) -> UUID4 | None | NotSet:
        return NOT_SET

    @property
    def household_id(self) -> UUID4 | None | NotSet:
        return NOT_SET

    model_config = ConfigDict(arbitrary_types_allowed=True)


